import EfiPy2 as EfiPy
from EfiPy2.MdePkg.IndustryStandard import EFIPY_INDUSTRY_STRUCTURE, EFIPY_INDUSTRY_UNION
import EfiPy2.MdePkg.IndustryStandard.Pci as pci
import pciids

PCI_ACCESS_MCFG = 'mcfg'
PCI_ACCESS_IO   = 'io'

class PCI_DEVICE_INDEPENDENT_REGION_UNION (EFIPY_INDUSTRY_UNION):

  _fields_ = [
    ('Hdr',   pci.PCI_DEVICE_INDEPENDENT_REGION),
    ('Raw',   EfiPy.UINT32 * (EfiPy.sizeof (pci.PCI_DEVICE_INDEPENDENT_REGION) // EfiPy.sizeof (EfiPy.UINT32))),
    ('Raw16', EfiPy.UINT16 * (EfiPy.sizeof (pci.PCI_DEVICE_INDEPENDENT_REGION) // EfiPy.sizeof (EfiPy.UINT16))),
  ]

def PciRegRead32 (Bus: int = 0, Dev: int = 0, Func: int = 0, Reg: int = 0) -> int:
  from EfiPy2.Lib.X86Processor import Me

  reg = pci.PCI_CONFIG_ACCESS_CF8 ((Reg & 0xFC, Func, Dev, Bus, 0, 1))
  return Me.IndexDatar32 (0xCF8, 0xCFC, reg.Uint32)

def _BuildPciStructType (PciHdr):
  PciTypeFields = [
    ('Hdr', pci.PCI_DEVICE_INDEPENDENT_REGION),
  ]

  if pci.IS_PCI_BRIDGE (PciHdr):
    # Type 1
    PciTypeFields.append (('Cfg', pci.PCI_BRIDGE_CONTROL_REGISTER))
  elif pci.IS_CARDBUS_BRIDGE (PciHdr):
    # Type 2
    PciTypeFields.append (('Cfg', pci.PCI_CARDBUS_CONTROL_REGISTER))
  else:
    # Type 0
    PciTypeFields.append (('Cfg', pci.PCI_DEVICE_HEADER_TYPE_REGION))

  class PciStruct (EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = PciTypeFields

  return PciStruct

def BuildPciHeaderMcfg (EcamBase: int, Bus: int, Dev: int, Func: int):
  PciCfgAddress = EcamBase + pci.PCI_ECAM_ADDRESS (Bus, Dev, Func, 0)
  PciHdr        = PCI_DEVICE_INDEPENDENT_REGION_UNION.from_address (PciCfgAddress)

  if PciHdr.Hdr.VendorId in (0xFFFF, 0x0000):
    return None, None

  PciStruct = _BuildPciStructType (PciHdr)
  PciCfg    = PciStruct.from_address (PciCfgAddress)

  return PciCfg, PciStruct

def BuildPciHeaderIo (Bus: int, Dev: int, Func: int):
  PciHdr = PCI_DEVICE_INDEPENDENT_REGION_UNION ()
  PciHdr.Raw[0] = PciRegRead32 (Bus, Dev, Func, 0)

  if PciHdr.Hdr.VendorId in (0xFFFF, 0x0000):
    return None, None

  for idx in range (4, EfiPy.sizeof (pci.PCI_DEVICE_INDEPENDENT_REGION), 4):
    PciHdr.Raw[idx // 4] = PciRegRead32 (Bus, Dev, Func, idx)

  PciStruct = _BuildPciStructType (PciHdr)

  class PciUnion (EFIPY_INDUSTRY_UNION):
    _fields_ = [
      ('Pci', PciStruct),
      ('Raw', EfiPy.UINT32 * (EfiPy.sizeof (PciStruct) // EfiPy.sizeof (EfiPy.UINT32))),
    ]

  PciCfg = PciUnion ()
  for i in range (len (PciHdr.Raw)):
    PciCfg.Raw[i] = PciHdr.Raw[i]

  for idx in range (EfiPy.sizeof (pci.PCI_DEVICE_INDEPENDENT_REGION), EfiPy.sizeof (PciStruct), 4):
    PciCfg.Raw[idx // 4] = PciRegRead32 (Bus, Dev, Func, idx)

  return PciCfg.Pci, PciStruct

def BuildPciHeader (Bus: int, Dev: int, Func: int, AccessMode: str = PCI_ACCESS_MCFG, EcamBase: int = 0):
  if AccessMode == PCI_ACCESS_MCFG:
    return BuildPciHeaderMcfg (EcamBase, Bus, Dev, Func)
  elif AccessMode == PCI_ACCESS_IO:
    return BuildPciHeaderIo (Bus, Dev, Func)
  else:
    raise ValueError (f"Unsupported AccessMode: {AccessMode}")

def _GetSegmentRanges (AccessMode: str = PCI_ACCESS_MCFG, Segment: int = None) -> list:
  Mode = AccessMode.lower () if isinstance (AccessMode, str) else AccessMode

  if Mode == PCI_ACCESS_MCFG:
    from EfiPy2.Lib.Acpi.AcpiRetrieve   import ExtractTable
    from EfiPy2.Lib.Acpi.AcpiMcfgParser import AcpiMcfgParser

    AcpiRaw    = ExtractTable (b'MCFG', 0)
    AcpiObj, _ = AcpiMcfgParser (AcpiRaw)

    ranges = []
    for McfgDesc in AcpiObj.McfgDesc:
      if Segment is not None and McfgDesc.PciSegmentGroupNumber != Segment:
        continue
      ranges.append ((
        McfgDesc.PciSegmentGroupNumber,
        McfgDesc.StartBusNumber,
        McfgDesc.EndBusNumber,
        PCI_ACCESS_MCFG,
        McfgDesc.BaseAddress,
      ))
    return ranges

  elif Mode == PCI_ACCESS_IO:
    if Segment not in (None, 0):
      return []
    return [(0, 0, pci.PCI_MAX_BUS, PCI_ACCESS_IO, 0)]

  else:
    raise ValueError (f"Unsupported AccessMode: {AccessMode}")

def _IterBusDevices (Segment: int, Bus: int, AccessMode: str, EcamBase: int = 0):
  for Dev in range (pci.PCI_MAX_DEVICE + 1):
    for Func in range (pci.PCI_MAX_FUNC + 1):

      PciObj, PciType = BuildPciHeader (Bus, Dev, Func, AccessMode = AccessMode, EcamBase = EcamBase)

      if PciObj is None:
        if Func == 0:
          break
        continue

      IsMulti  = pci.IS_PCI_MULTI_FUNC (PciObj)
      IsBridge = pci.IS_PCI_BRIDGE (PciObj)

      dev_entry = {
        "mode":      AccessMode,
        "segment":   Segment,
        "bus":       Bus,
        "dev":       Dev,
        "func":      Func,
        "vid":       PciObj.Hdr.VendorId,
        "did":       PciObj.Hdr.DeviceId,
        "rev":       PciObj.Hdr.RevisionID,
        "class":     tuple (PciObj.Hdr.ClassCode[:]),
        "pci_obj":   PciObj,
        "pci_type":  PciType,
        "is_multi":  IsMulti,
        "is_bridge": IsBridge,
        "pri_bus":   PciObj.Cfg.PrimaryBus if IsBridge else Bus,
        "sec_bus":   PciObj.Cfg.SecondaryBus if IsBridge else 0,
        "sub_bus":   PciObj.Cfg.SubordinateBus if IsBridge else 0,
        "children":  [],
      }

      yield dev_entry

      if Func == 0 and not IsMulti:
        break

def IterPciDevices (AccessMode: str = PCI_ACCESS_MCFG, Segment: int = None):
  for Seg, StartBus, EndBus, Mode, EcamBase in _GetSegmentRanges (AccessMode = AccessMode, Segment = Segment):
    for Bus in range (StartBus, EndBus + 1):
      yield from _IterBusDevices (Seg, Bus, Mode, EcamBase)

def ScanPciDevices (AccessMode: str = PCI_ACCESS_MCFG, Segment: int = None) -> list:
  return list (IterPciDevices (AccessMode = AccessMode, Segment = Segment))

def PrintPciDevice (dev: dict, AccessMode: str = PCI_ACCESS_MCFG) -> None:
  Seg        = dev["segment"]
  Bus        = dev["bus"]
  Dev        = dev["dev"]
  Func       = dev["func"]
  VendorId   = dev["vid"]
  DeviceId   = dev["did"]
  RevisionID = dev["rev"]
  Interface, SubClass, BaseClass = dev["class"]

  DeviceClass, SubClassDict = pciids.PciClass.get (BaseClass, (f"Class {BaseClass:02X}", {}))
  SubName, ProgIfDict       = SubClassDict.get (SubClass, (f"SubClass {SubClass:02X}", {}))
  ProgIfName                = ProgIfDict.get (Interface, f"ProgIf {Interface:02X}")
  VendorName, DeviceDict    = pciids.PciIds.get (VendorId, (f"Vendor {VendorId:04X}", {}))
  DeviceName, _             = DeviceDict.get (DeviceId, (f"Device {DeviceId:04X}", {}))

  if AccessMode == PCI_ACCESS_IO:
    bdf_prefix = f"{Bus:02X}:{Dev:02X}.{Func:X}"
  else:
    bdf_prefix = f"{Seg:04X}:{Bus:02X}:{Dev:02X}.{Func:X}"

  print (f"{bdf_prefix} {SubName}: {ProgIfName} ({BaseClass:X},{SubClass:X},{Interface:X}): {VendorName}: {DeviceName} ({VendorId:04X} {DeviceId:04X} rev: {RevisionID:02X})", flush = True)

def PrintPciDeviceList (AccessMode: str = PCI_ACCESS_MCFG, Segment: int = None, DeviceList = None) -> None:
  devices = DeviceList if DeviceList is not None else IterPciDevices (AccessMode = AccessMode, Segment = Segment)

  for dev in devices:
    PrintPciDevice (dev, AccessMode = AccessMode)

def _AttachBusChildren (Bus: int, EndBus: int, BusMap: dict, Visited: set) -> list:
  if Bus > EndBus or Bus in Visited:
    return []
  Visited.add (Bus)

  bus_devices = []
  for dev in BusMap.get (Bus, []):
    dev_copy = dict (dev)
    dev_copy["children"] = []

    if (dev_copy["is_bridge"] and
        Bus < dev_copy["sec_bus"] <= dev_copy["sub_bus"] and
        dev_copy["sec_bus"] <= EndBus):
      sub_limit = min (dev_copy["sub_bus"], EndBus)
      dev_copy["children"] = _AttachBusChildren (
        dev_copy["sec_bus"], sub_limit, BusMap, Visited
      )
      Visited.update (range (dev_copy["sec_bus"], sub_limit + 1))

    bus_devices.append (dev_copy)

  return bus_devices

def BuildPciTree (DeviceList: list = None, AccessMode: str = PCI_ACCESS_MCFG, Segment: int = None) -> list:
  if DeviceList is None:
    DeviceList = ScanPciDevices (AccessMode = AccessMode, Segment = Segment)

  SegMap = {}
  for dev in DeviceList:
    seg = dev["segment"]
    bus = dev["bus"]
    SegMap.setdefault (seg, {}).setdefault (bus, []).append (dev)

  root_trees = []
  for seg in sorted (SegMap.keys ()):
    BusMap  = SegMap[seg]
    Visited = set ()
    max_bus = max (BusMap.keys ()) if BusMap else 0

    for Bus in range (0, max_bus + 1):
      if Bus in Visited or Bus not in BusMap:
        continue
      devices = _AttachBusChildren (Bus, pci.PCI_MAX_BUS, BusMap, Visited)
      if devices:
        max_sub = max ([Bus] + [d["sub_bus"] for d in devices if d["is_bridge"]])
        root_trees.append ({
          "mode":    AccessMode,
          "segment": seg,
          "bus":     Bus,
          "max_sub": max_sub,
          "devices": devices,
        })

  return root_trees

def GetDeviceDesc (VendorId: int, DeviceId: int) -> str:
  VendorName, DeviceDict = pciids.PciIds.get (VendorId, (f"Vendor {VendorId:04x}", {}))
  DeviceName, _          = DeviceDict.get (DeviceId, (f"Device {DeviceId:04x}", {}))
  return f"{VendorName} {DeviceName} [{VendorId:04x}:{DeviceId:04x}]"

def _PrintBusTree (devices: list, line_prefix: str, cont_prefix: str, is_root: bool = False,
                   ScanCtx: dict = None) -> None:
  if not devices:
    if is_root:
      print (line_prefix, flush = True)
    return

  total = len (devices)
  for idx, dev in enumerate (devices):
    is_first = (idx == 0)
    is_last  = (idx == total - 1)

    conn = "\\-" if is_last else "+-"

    dev_line_prefix = (line_prefix if (is_first and is_root) else cont_prefix) + conn
    branch_bar      = "  " if is_last else "| "
    dev_cont_prefix = cont_prefix + branch_bar

    bdf_str = f"{dev['bus']:02x}:{dev['dev']:02x}.{dev['func']:x}"
    desc    = GetDeviceDesc (dev["vid"], dev["did"])

    if dev["is_bridge"]:
      sec = dev["sec_bus"]
      sub = dev["sub_bus"]
      bus_tag = f"-[{sec:02x}-{sub:02x}]--"

      print (f"{dev_line_prefix}{bdf_str}{bus_tag}  {desc}", flush = True)

      children = dev["children"]
      if ScanCtx is not None and not children:
        Bus     = dev["bus"]
        EndBus  = ScanCtx["end_bus"]
        Visited = ScanCtx["visited"]
        if Bus < sec <= sub and sec <= EndBus and sec not in Visited:
          sub_limit = min (sub, EndBus)
          Visited.add (sec)
          children = list (_IterBusDevices (
            ScanCtx["segment"], sec, ScanCtx["mode"], ScanCtx["ecam_base"]
          ))
          sub_ctx = dict (ScanCtx, end_bus = sub_limit)
          if children:
            child_cont_prefix = dev_cont_prefix + " " * (len (bdf_str) + len (bus_tag))
            _PrintBusTree (children, child_cont_prefix, child_cont_prefix, is_root = False, ScanCtx = sub_ctx)
          Visited.update (range (sec, sub_limit + 1))
          continue

      if children:
        child_cont_prefix = dev_cont_prefix + " " * (len (bdf_str) + len (bus_tag))
        _PrintBusTree (children, child_cont_prefix, child_cont_prefix, is_root = False, ScanCtx = ScanCtx)
    else:
      print (f"{dev_line_prefix}{bdf_str}  {desc}", flush = True)

def PrintBusTree (AccessMode: str = PCI_ACCESS_MCFG, Segment: int = None, DeviceList: list = None) -> None:
  print (f"Access Mode: {AccessMode}", flush = True)
  if DeviceList is not None:
    root_trees = BuildPciTree (DeviceList = DeviceList, AccessMode = AccessMode, Segment = Segment)
    for root in root_trees:
      Seg     = root["segment"]
      Bus     = root["bus"]
      max_sub = root["max_sub"]
      devices = root["devices"]

      root_prefix = (f"-[{Seg:04x}:{Bus:02x}]---" if max_sub == Bus
                     else f"-[{Seg:04x}:{Bus:02x}-{max_sub:02x}]-")
      root_cont   = " " * len (root_prefix)
      _PrintBusTree (devices, root_prefix, root_cont, is_root = True)
    return

  for Seg, StartBus, EndBus, Mode, EcamBase in _GetSegmentRanges (AccessMode = AccessMode, Segment = Segment):
    Visited = set ()
    ScanCtx = {
      "segment":   Seg,
      "end_bus":   EndBus,
      "mode":      Mode,
      "ecam_base": EcamBase,
      "visited":   Visited,
    }
    for Bus in range (StartBus, EndBus + 1):
      if Bus in Visited:
        continue
      Visited.add (Bus)
      devices = list (_IterBusDevices (Seg, Bus, Mode, EcamBase))
      if devices:
        max_sub     = max ([Bus] + [d["sub_bus"] for d in devices if d["is_bridge"]])
        root_prefix = (f"-[{Seg:04x}:{Bus:02x}]---" if max_sub == Bus
                       else f"-[{Seg:04x}:{Bus:02x}-{max_sub:02x}]-")
        root_cont   = " " * len (root_prefix)
        _PrintBusTree (devices, root_prefix, root_cont, is_root = True, ScanCtx = ScanCtx)
